    fix: {
      M_CR7_JBR_PLACE: M('Jesus is called Jesus of Nazareth.', 'Read Luke 2:4-7: from Nazareth to Bethlehem for the census.', 'Says Jesus was born in Nazareth, his hometown, instead of Bethlehem.'),
      M_CR7_JBR_ANGEL: M('Michael is the angel named in songs and other books.', 'Read Luke 1:26: Gabriel. He also went to Zechariah.', 'Names Michael instead of Gabriel as the angel who came to Mary.'),
      M_CR7_JBR_DEDICATION: M('Dedication and baptism are both church ceremonies for babies or new believers.', 'Read Luke 2:22-24: in the temple at Jerusalem, with an offering of two doves. Jesus\' baptism came at about thirty.', 'Places Jesus\' dedication in the River Jordan, mixing it with his baptism as an adult, instead of the temple in Jerusalem.'),
    },
    mis: [['M_CR7_JBR_SIMEON', 'Forgets Simeon and Anna, who recognised the baby at the dedication.', 'Who took baby Jesus in his arms in the temple and praised God (Luke 2:25-28)?', 'The high priest Caiaphas', 'Simeon, a righteous and devout man', 'Caiaphas is the priest the learner knows from Easter.', 'Read Luke 2:25-38 and draw Simeon and Anna with the baby.', 'Simeon took Jesus in his arms and praised God, and the prophet Anna gave thanks.']],
    pack: P('The learner elaborates the annunciation and birth of Jesus (Luke 1:26-38; 2:1-7), describes the dedication in the temple (Luke 2:22-38: offering of two doves, Simeon and Anna), and relates it to similar practices in churches today (dedication or infant baptism, as each church does it).',
      ['Knows the prophecies about the Messiah.', 'Which town did Micah 5:2 name?', 'Bethlehem'],
      ['a map: Nazareth, Bethlehem, Jerusalem', 'Luke 2:22-38 in a sequence strip', 'pictures of Simeon and Anna'],
      ['Gabriel comes to Mary.', 'Jesus is born in Bethlehem.', 'He is dedicated in the temple.', 'Simeon and Anna praise God.'],
      ['a baby dedication at church', 'Christmas celebrations', 'thanking God for a new baby'],
      B('Draw a map with Nazareth, Bethlehem and Jerusalem.', 'Point at Jerusalem.', 'What happened here when Jesus was a baby?', 'Wait for the learner to say he was dedicated in the temple.', 'Add Simeon and Anna to the picture.'),
      [['Where was Jesus born?', 'Bethlehem', 'place'], ['Where was Jesus dedicated?', 'In the temple at Jerusalem', 'dedication']]),
