  SEXUALITY_BASICS: {
    also: ['d', 'e'],
    pre: [['G6:SEXUALITY_BIBLE', 'Biblical teaching on responsible behaviour, met in Grade 6.'], ['G6:SEXUALITY_SKILLS', 'Values and life skills to avoid irresponsible behaviour.']],
    fix: {
      M_CR7_SB_SHAME: M('Shame and fear of blame keep learners silent.', 'Name trusted adults and say clearly: it is never the young person\'s fault; telling is right.'),
      M_CR7_SB_HEALTHY: M('Pressure can look like love in films.', 'Sort cards: respect, honesty, trust, parents know (healthy); pressure, secrets, gifts for favours (unhealthy).', 'Thinks pressure to prove love is part of a healthy relationship.', 'A boyfriend says "if you love me you will prove it". Is this healthy?', 'Yes, that is what love is', 'No: pressure is a sign of an unhealthy relationship'),
      M_CR7_SB_PART: M('The word sexuality is heard only as body parts or sex.', 'Explain sexuality as being made male and female in God\'s image (Genesis 1:27), with feelings, relationships and roles.'),
    },
    mis: [
      ['M_CR7_SB_NO_CONSEQUENCE', 'Thinks sex before marriage has no consequences if no one finds out.', 'Name one consequence of sex before marriage.', 'None, if no one finds out', 'Early pregnancy, infections, dropping out of school, guilt and broken trust', 'The learner thinks consequences come only from being caught.', 'List consequences in four groups: health, school, family, faith. Read 1 Corinthians 6:18.', 'Sex before marriage can bring early pregnancy, infections, leaving school and broken trust, whether or not anyone finds out.'],
      ['M_CR7_SB_CHASTE_IMPOSSIBLE', 'Thinks no young person can stay chaste until marriage, so the teaching is pointless.', 'Is it possible for a young person to remain chaste until marriage?', 'No, nobody can', 'Yes: with God\'s help, good friends, self-control and avoiding tempting places', 'Media and peers say "everyone is doing it".', 'Read 1 Thessalonians 4:3-4 and Philippians 4:8. List the skills that help: self-control, assertiveness, good friends, prayer.', 'Yes, many young people stay chaste. God\'s help, good friends and self-control make it possible.', FAITH],
    ],
    pack: P('The learner explains human sexuality (made male and female in God\'s image), discusses healthy and unhealthy relationships and the circumstances that lead to unhealthy ones (idleness, bad company, media, being alone in tempting places), outlines consequences of sex before marriage, and compiles values and life skills to avoid it (chastity, self-control, assertiveness, decision-making; 1 Corinthians 6:18; 1 Thessalonians 4:3).',
      ['Knows the biblical teaching on the body.', 'What does 1 Corinthians 6:19 call your body?', 'A temple of the Holy Spirit'],
      ['two columns: healthy and unhealthy', '1 Thessalonians 4:3 written large', 'a skills list'],
      ['Explain sexuality.', 'Sort healthy and unhealthy signs.', 'List consequences of sex before marriage.', 'Compile values and life skills.'],
      ['a party with no adults', 'pressure from an older youth', 'a phone message asking for photos'],
      B('Draw two columns: healthy and unhealthy.', 'Point at the card "keeps it secret from parents".', 'Which column?', 'Wait for the learner to say unhealthy.', 'List the consequences and the skills that help.'),
      [['Which is part of a healthy relationship?', 'Respect and honesty', 'healthy'], ['Name one consequence of sex before marriage.', 'Early pregnancy (infections, leaving school)', 'consequence']]),
  },
